class MainActivity : ComponentActivity() {
    private val widgetAction = mutableStateOf<String?>(null)
    internal var nativeStateForLifecycle: JSONObject? = null
    internal var nativeRepoForLifecycle: HouseholdRepository? = null
    override fun onNewIntent(intent: Intent) { super.onNewIntent(intent); setIntent(intent); widgetAction.value=intent.getStringExtra(BetaWidgetProvider.EXTRA_BETA_ACTION) }
    override fun onStop() { nativeStateForLifecycle?.let { nativeRepoForLifecycle?.autoBackup(it) }; super.onStop() }
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        widgetAction.value=intent?.getStringExtra(BetaWidgetProvider.EXTRA_BETA_ACTION)
        setContent {
            val activity=this@MainActivity
            val themeRepo=remember{HouseholdRepository(activity)}
            var themeRevision by remember{mutableStateOf(0)}
            val choice=remember(themeRevision){themeRepo.getSetting("household-theme")?.takeIf{it in setOf("light","dark","system")} ?: "system"}
            val systemDark=androidx.compose.foundation.isSystemInDarkTheme()
            val dark=choice=="dark" || (choice=="system" && systemDark)
            MaterialTheme(
                colorScheme = if (dark) darkColorScheme(primary=Color(0xFF5B9CFF), background=Color(0xFF0F1013), surface=Color(0xFF1E1F24), onBackground=Color(0xFFF2F2F4), onSurface=Color(0xFFF2F2F4))
                else lightColorScheme(primary=Blue, background=Paper, surface=SurfaceSolid, onBackground=Ink, onSurface=Ink)
            ) { CompositionLocalProvider(LocalAppDark provides dark) { NativeApp(onThemeChanged={themeRevision++},initialWidgetAction=widgetAction.value,onWidgetActionConsumed={widgetAction.value=null}) } }
        }
    }
}

private class HouseholdRepository(private val activity: Activity) {
    private val store = NativeKeyValueStore.getInstance(activity)
    private val key = "household-data-v8"
    fun load(): JSONObject = runCatching { JSONObject(store.getItem(key) ?: "{}") }.getOrDefault(JSONObject())
    fun save(state: JSONObject) = store.setItem(key, state.toString())
    fun getSetting(name:String):String? = store.getItem(name)
    fun setSetting(name:String,value:String) = store.setItem(name,value)
    fun removeSetting(name:String) = store.removeItem(name)
    fun autoBackup(state:JSONObject){if(getSetting("haushaltsbuch-autobackup-enabled")!="1")return;val raw=getSetting("haushaltsbuch-autobackup-uri")?:return;runCatching{val tree=DocumentFile.fromTreeUri(activity,Uri.parse(raw))?:return;val file=tree.findFile("haushaltsbuch-auto-backup.csv")?:tree.createFile("text/csv","haushaltsbuch-auto-backup.csv")?:return;activity.contentResolver.openOutputStream(file.uri,"wt")?.bufferedWriter()?.use{it.write(buildBackup(state))}}}
    fun buildBackup(state:JSONObject):String{val tables=listOf("income" to listOf("id","name","amount"),"fixedExpenses" to listOf("id","name","amount","icon"),"openInvoices" to listOf("id","name","amount","dueDate","paid","paidDate"),"variableCosts" to listOf("id","name","monthlyAmount","actualAmount","interval","dueMonth","dueYear"),"variableContributions" to listOf("id","date","amount","note"),"variablePayments" to listOf("id","itemId","itemName","date","amount"),"loans" to listOf("id","name","originalAmount","remainingBalance","monthlyPayment","totalTermMonths","paidOffDate","carryoverPct","totalWithInterest","monthlyRate","lastReconciledBalance","lastReconciledDate"),"loanPayments" to listOf("id","loanId","date","amount","type"),"savings" to listOf("id","date","amount","type","comment"),"cars" to listOf("id","name"),"fuelLogs" to listOf("id","carId","liters","pricePerLiter","date"),"betaEntries" to listOf("id","type","title","date","amount","category","recurring","reconciled","isRecurringTemplate","recurrencePeriod","recurrenceEnd","recurringGroupId"));fun esc(v:Any?):String{val s=if(v==null||v==JSONObject.NULL)"" else v.toString();return if(s.any{it==','||it=='"'||it=='\n'}) "\""+s.replace("\"","\"\"")+"\"" else s};val out=mutableListOf<String>();tables.forEach{(name,cols)->val lines=mutableListOf("# TABLE:$name",cols.joinToString(","));array(state,name).objects().forEach{o->lines+=cols.joinToString(","){esc(o.opt(it))}};out+=lines.joinToString("\n")};out+=listOf("# TABLE:settings","amount",esc(state.optDouble("potCarryover",0.0))).joinToString("\n");val vis=getSetting("household-tab-visibility")?:"{}";val extra=getSetting("household-tilgung-extra")?:"0";val current=getSetting("household-tilgung-current-month")?:"";out+=listOf("# TABLE:appSettings","tabVisibilityJson,tilgungExtra,tilgungCurrentMonth",listOf(esc(vis),esc(extra),esc(current)).joinToString(",")).joinToString("\n");return out.joinToString("\n\n")}
    fun restoreBackup(text:String):JSONObject{
        fun rows(s:String):List<List<String>>{val out=mutableListOf<List<String>>();var row=mutableListOf<String>();val field=StringBuilder();var quoted=false;var i=0;while(i<s.length){val ch=s[i];if(quoted){if(ch=='"'&&i+1<s.length&&s[i+1]=='"'){field.append('"');i++}else if(ch=='"')quoted=false else field.append(ch)}else when(ch){'"'->quoted=true;','->{row.add(field.toString());field.clear()};'\n'->{row.add(field.toString());field.clear();out.add(row);row=mutableListOf()};'\r'->{};else->field.append(ch)};i++};if(field.isNotEmpty()||row.isNotEmpty()){row.add(field.toString());out.add(row)};return out}
        val result=JSONObject();listOf("income","fixedExpenses","openInvoices","variableCosts","variableContributions","variablePayments","loans","loanPayments","savings","cars","fuelLogs","betaEntries").forEach{result.put(it,JSONArray())};result.put("potCarryover",0.0)
        var table:String?=null;var cols:List<String>?=null
        rows(text).forEach{r->if(r.isEmpty())return@forEach;val first=r[0].trim();if(first.startsWith("# TABLE:")){table=first.removePrefix("# TABLE:").trim();cols=null;return@forEach};if(r.all{it.isBlank()})return@forEach;if(cols==null){cols=r.map{it.trim()};return@forEach};val map=cols!!.mapIndexed{i,k->k to r.getOrElse(i){""}}.toMap();when(table){"settings"->result.put("potCarryover",map["amount"]?.toDoubleOrNull()?:0.0);"appSettings"->{map["tabVisibilityJson"]?.takeIf{it.isNotBlank()}?.let{setSetting("household-tab-visibility",it)};map["tilgungExtra"]?.takeIf{it.isNotBlank()}?.let{setSetting("household-tilgung-extra",it)};map["tilgungCurrentMonth"]?.takeIf{it.isNotBlank()}?.let{setSetting("household-tilgung-current-month",it)}};else->{val a=result.optJSONArray(table?:"")?:return@forEach;val o=JSONObject();map.forEach{(k,v)->val value:Any=when{k in setOf("amount","monthlyAmount","actualAmount","originalAmount","remainingBalance","monthlyPayment","totalWithInterest","monthlyRate","lastReconciledBalance","liters","pricePerLiter")->v.toDoubleOrNull()?:0.0;k in setOf("dueMonth","dueYear","totalTermMonths","carryoverPct")->v.toIntOrNull()?:JSONObject.NULL;k in setOf("paid","recurring","reconciled","isRecurringTemplate")->v=="true"||v=="1";else->if(v.isBlank())JSONObject.NULL else v};o.put(k,value)};if(table=="variableCosts"&&!o.has("interval"))o.put("interval","jaehrlich");if(table=="loanPayments"&&(o.isNull("type")||o.optString("type").isBlank()))o.put("type","payment");a.put(o)}}}
        save(result);return result
    }
    fun emptyState():JSONObject=JSONObject().also{state->listOf("income","fixedExpenses","openInvoices","variableCosts","variableContributions","variablePayments","loans","loanPayments","savings","cars","fuelLogs","betaEntries","betaHiddenTitles").forEach{state.put(it,JSONArray())};state.put("potCarryover",0.0)}
    fun array(state: JSONObject, name: String): JSONArray = state.optJSONArray(name) ?: JSONArray().also { state.put(name, it) }
}

private fun JSONArray.objects(): List<JSONObject> = (0 until length()).mapNotNull { optJSONObject(it) }
private fun money(v: Double): String = NumberFormat.getCurrencyInstance(Locale.GERMANY).format(v)
private fun sum(a: JSONArray, field: String, predicate: (JSONObject)->Boolean = { true }): Double = a.objects().filter(predicate).sumOf { it.optDouble(field, 0.0) }

