private fun centInput(raw:String):String{val d=raw.filter{it.isDigit()}.trimStart('0').takeLast(9);if(d.isEmpty())return "";val n=d.toLong();return String.format(Locale.GERMANY,"%d,%02d",n/100,n%100)}
private fun milliInput(raw:String):String{val d=raw.filter{it.isDigit()}.trimStart('0').takeLast(9);if(d.isEmpty())return "";val n=d.toLong();return String.format(Locale.GERMANY,"%d,%03d",n/1000,n%1000)}
private fun solveMonthlyRate(principal:Double,monthly:Double,total:Double):Double?{if(principal==0.0||monthly==0.0||total==0.0||total<=principal)return null;val n=total/monthly;if(n<1)return null;var r=.01;repeat(60){val pow=(1+r).pow(-n);val fv=monthly*(1-pow)/r-principal;val h=.00001;val powH=(1+r+h).pow(-n);val fH=monthly*(1-powH)/(r+h)-principal;val deriv=(fH-fv)/h;if(kotlin.math.abs(deriv)<1e-9)return@repeat;var nr=r-fv/deriv;if(nr<=0)nr=r/2;if(kotlin.math.abs(nr-r)<1e-9){r=nr;return@repeat};r=nr};return if(r>0&&r.isFinite())r else null}

private fun betaAddPeriod(date:LocalDate,period:String):LocalDate=when(period){"weekly"->date.plusWeeks(1);"biweekly"->date.plusWeeks(2);"4weekly"->date.plusWeeks(4);"2monthly"->date.plusMonths(2);"3monthly","quarterly"->date.plusMonths(3);"6monthly"->date.plusMonths(6);"yearly"->date.plusYears(1);else->date.plusMonths(1)}
private fun generateBetaRecurringOccurrences(state:JSONObject,repo:HouseholdRepository,viewMonth:YearMonth):Boolean{
 val entries=repo.array(state,"betaEntries");val all=entries.objects();val templates=all.filter{it.optBoolean("isRecurringTemplate")}
 var horizon=LocalDate.now().plusMonths(2);val viewedEnd=viewMonth.atEndOfMonth();if(viewedEnd.isAfter(horizon))horizon=viewedEnd
 var changed=false
 templates.forEach{tpl->
  val existing=repo.array(state,"betaEntries").objects().filter{it.optString("id")==tpl.optString("id")||it.optString("recurringGroupId")==tpl.optString("id")}.map{it.optString("date")}.toMutableSet()
  val start=runCatching{LocalDate.parse(tpl.optString("date"))}.getOrNull()?:return@forEach
  val end=tpl.optString("recurrenceEnd").takeIf{it.isNotBlank()&&it!="null"}?.let{runCatching{LocalDate.parse(it)}.getOrNull()}
  val period=tpl.optString("recurrencePeriod","monthly");var cursor=betaAddPeriod(start,period);var guard=0
  while(!cursor.isAfter(horizon)&&guard<240){guard++;if(end!=null&&cursor.isAfter(end))break;val key=cursor.toString();if(key !in existing){entries.put(JSONObject().put("id",UUID.randomUUID().toString()).put("type",tpl.optString("type")).put("title",tpl.optString("title")).put("date",key).put("amount",tpl.optDouble("amount")).put("category",tpl.optString("category")).put("recurring",true).put("recurringGroupId",tpl.optString("id")).put("reconciled",false));existing+=key;changed=true};cursor=betaAddPeriod(cursor,period)}
 }
 return changed
}
@Composable private fun BalanceScreen(state:JSONObject,repo:HouseholdRepository,month:YearMonth,prev:()->Unit,next:()->Unit,onMonthSelected:(YearMonth)->Unit,onEntryClick:(JSONObject)->Unit,onToggleReconciled:(JSONObject)->Unit){
    LaunchedEffect(month){if(generateBetaRecurringOccurrences(state,repo,month))repo.persist(state)}
    val all=repo.array(state,"betaEntries").objects()
    val monthEntries=all.filter{runCatching{YearMonth.from(LocalDate.parse(it.optString("date")))==month}.getOrDefault(false)}
    val income=monthEntries.filter{it.optString("type")=="einnahme" || it.optString("type")=="income"}.sumOf{it.optDouble("amount")}
    val expense=monthEntries.filterNot{it.optString("type")=="einnahme" || it.optString("type")=="income"}.sumOf{it.optDouble("amount")}
    val cutoff=month.atEndOfMonth()
    val balance=all.filter{runCatching{!LocalDate.parse(it.optString("date")).isAfter(cutoff)}.getOrDefault(false)}.sumOf{if(it.optString("type")=="einnahme"||it.optString("type")=="income")it.optDouble("amount") else -it.optDouble("amount")}
    var filter by remember{mutableStateOf("all")};var monthPicker by remember{mutableStateOf(false)};var yearPicker by remember{mutableStateOf(false)}
    val unreconciled=monthEntries.count{!it.optBoolean("reconciled")}
    val shown=if(filter=="unreconciled")monthEntries.filter{!it.optBoolean("reconciled")}else monthEntries
    val groups=shown.groupBy{it.optString("date")}.toSortedMap(compareByDescending{it})
    val listState=rememberLazyListState()
    var barCollapsed by remember(month){mutableStateOf(false)}
    var lastScrollOffset by remember(month){mutableStateOf(0)}
    LaunchedEffect(listState.firstVisibleItemIndex,listState.firstVisibleItemScrollOffset){val current=if(listState.firstVisibleItemIndex==0)listState.firstVisibleItemScrollOffset else Int.MAX_VALUE;if(current<=8){barCollapsed=false;lastScrollOffset=current}else if(current!=Int.MAX_VALUE&&lastScrollOffset!=Int.MAX_VALUE&&current-lastScrollOffset>24){barCollapsed=true;lastScrollOffset=current}else if(current==Int.MAX_VALUE){barCollapsed=true;lastScrollOffset=current}else if(kotlin.math.abs(current-lastScrollOffset)>24){lastScrollOffset=current}}
    Column(Modifier.fillMaxSize().subViewSwipe(listOf("all","unreconciled"),filter){filter=it}){
        Box(Modifier.animateContentSize()){if(!barCollapsed)IncomeExpenseBar(income,expense)}
        Surface(color=MaterialTheme.colorScheme.surface.copy(alpha=.35f),shape=RoundedCornerShape(bottomStart=20.dp,bottomEnd=20.dp)){
            Row(Modifier.fillMaxWidth().padding(horizontal=18.dp,vertical=10.dp),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.SpaceBetween){
                Surface(shape=CircleShape,color=MaterialTheme.colorScheme.surface,modifier=Modifier.size(40.dp).clickable(onClick=prev)){Box(contentAlignment=Alignment.Center){ChevronIcon(left=true,color=MaterialTheme.colorScheme.onSurface)}}
                Column(horizontalAlignment=Alignment.CenterHorizontally){
                    Row{Text(month.format(DateTimeFormatter.ofPattern("MMMM",Locale.GERMAN)).replaceFirstChar{it.uppercase()},fontSize=19.sp,fontWeight=FontWeight.ExtraBold,modifier=Modifier.clickable{monthPicker=true});Spacer(Modifier.width(6.dp));Text(month.year.toString(),fontSize=19.sp,fontWeight=FontWeight.ExtraBold,modifier=Modifier.clickable{yearPicker=true})}
                    Text("Einnahmen +"+money(income)+" · Ausgaben -"+money(expense),fontSize=11.sp,fontWeight=FontWeight.SemiBold,color=MaterialTheme.colorScheme.onSurfaceVariant)
                }
                Surface(shape=CircleShape,color=MaterialTheme.colorScheme.surface,modifier=Modifier.size(40.dp).clickable(onClick=next)){Box(contentAlignment=Alignment.Center){ChevronIcon(left=false,color=MaterialTheme.colorScheme.onSurface)}}
            }
        }
        Row(Modifier.fillMaxWidth().padding(horizontal=18.dp,vertical=10.dp).background(MaterialTheme.colorScheme.background, RoundedCornerShape(14.dp)).padding(4.dp)){
            BetaFilter("Alle",filter=="all",Modifier.weight(1f)){filter="all"}
            BetaFilter("Nicht abgeglichen ($unreconciled)",filter=="unreconciled",Modifier.weight(1f)){filter="unreconciled"}
        }
        LazyColumn(Modifier.weight(1f),state=listState,contentPadding=PaddingValues(horizontal=18.dp,vertical=2.dp)){
            if(groups.isEmpty())item{Text(if(filter=="unreconciled")"Alles in diesem Monat ist abgeglichen." else "Noch keine Einträge in diesem Monat.",Modifier.fillMaxWidth().padding(30.dp),textAlign=TextAlign.Center,color=MaterialTheme.colorScheme.onSurfaceVariant)}
            groups.forEach{(date,entries)->item(key=date){BetaDayGroup(date,entries,onEntryClick,onToggleReconciled)}}
        }
        Row(Modifier.fillMaxWidth().background(if(balance>=0)appGreen(LocalAppDark.current) else appRed(LocalAppDark.current)).padding(horizontal=18.dp,vertical=10.dp),verticalAlignment=Alignment.CenterVertically){
            Text("Kontostand",fontSize=12.sp,fontWeight=FontWeight.Bold,color=Color.White.copy(alpha=.9f));Spacer(Modifier.width(10.dp));Text(money(balance),fontSize=19.sp,fontWeight=FontWeight.ExtraBold,color=Color.White,modifier=Modifier.weight(1f))
            Text("01."+month.monthValue.toString().padStart(2,'0')+"."+month.year+"\n- "+month.lengthOfMonth().toString().padStart(2,'0')+"."+month.monthValue.toString().padStart(2,'0')+"."+month.year,fontSize=10.5.sp,color=Color.White.copy(alpha=.85f),textAlign=TextAlign.End)
        }
    }
    if(monthPicker)AlertDialog(onDismissRequest={monthPicker=false},title={Text("Monat auswählen")},text={Column{listOf("Jan","Feb","Mär","Apr","Mai","Jun","Jul","Aug","Sep","Okt","Nov","Dez").chunked(3).forEachIndexed{r,row->Row(Modifier.fillMaxWidth()){row.forEachIndexed{c,label->val m=r*3+c+1;TextButton(onClick={onMonthSelected(YearMonth.of(month.year,m));monthPicker=false},modifier=Modifier.weight(1f)){Text(label,fontWeight=if(m==month.monthValue)FontWeight.ExtraBold else FontWeight.Normal)}}}}}},confirmButton={},dismissButton={TextButton(onClick={monthPicker=false}){Text("Abbrechen")}})
    if(yearPicker){val realYear=LocalDate.now().year;AlertDialog(onDismissRequest={yearPicker=false},title={Text("Jahr auswählen")},text={LazyColumn(Modifier.heightIn(max=420.dp)){items((realYear-10..realYear+10).toList()){y->TextButton(onClick={onMonthSelected(YearMonth.of(y,month.monthValue));yearPicker=false},modifier=Modifier.fillMaxWidth()){Text(y.toString(),fontWeight=if(y==month.year)FontWeight.ExtraBold else FontWeight.Normal)}}}},confirmButton={},dismissButton={TextButton(onClick={yearPicker=false}){Text("Abbrechen")}})}

}
@Composable private fun BetaFilter(label:String,active:Boolean,modifier:Modifier=Modifier,onClick:()->Unit){
    Surface(modifier.clickable(onClick=onClick),shape=RoundedCornerShape(11.dp),color=if(active)MaterialTheme.colorScheme.surface else Color.Transparent,shadowElevation=if(active)1.dp else 0.dp){Text(label,Modifier.padding(vertical=11.dp,horizontal=8.dp),textAlign=TextAlign.Center,fontSize=13.5.sp,fontWeight=FontWeight.Bold,color=if(active)MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.onSurfaceVariant)}
}
@Composable private fun BetaDayGroup(date:String,entries:List<JSONObject>,onEntryClick:(JSONObject)->Unit,onToggleReconciled:(JSONObject)->Unit){
    val d=runCatching{LocalDate.parse(date)}.getOrNull()
    val total=entries.sumOf{if(it.optString("type")=="einnahme"||it.optString("type")=="income")it.optDouble("amount") else -it.optDouble("amount")}
    Surface(Modifier.fillMaxWidth().padding(bottom=3.dp),shape=RoundedCornerShape(14.dp),color=MaterialTheme.colorScheme.surface){
        Column{
            Row(Modifier.fillMaxWidth().background(Brush.linearGradient(listOf(heroBlueStart(LocalAppDark.current),heroBlueEnd(LocalAppDark.current)))).padding(horizontal=14.dp,vertical=10.dp),verticalAlignment=Alignment.CenterVertically){
                Box(Modifier.size(34.dp).border(1.5.dp,heroBlueText(LocalAppDark.current),RoundedCornerShape(8.dp)),contentAlignment=Alignment.Center){Text((d?.dayOfMonth?:0).toString().padStart(2,'0'),fontSize=15.sp,fontWeight=FontWeight.ExtraBold,color=MaterialTheme.colorScheme.primary)}
                Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text("TAGESSALDO",fontSize=11.5.sp,fontWeight=FontWeight.ExtraBold,color=heroBlueText(LocalAppDark.current),letterSpacing=.23.sp);Text(if(d==null)"" else d.format(DateTimeFormatter.ofPattern("MMMM yyyy (EEEE)",Locale.GERMAN)),fontSize=11.sp,color=heroBlueSub(LocalAppDark.current))}
                Text((if(total>=0) "+" else "")+money(total),fontSize=15.sp,fontWeight=FontWeight.ExtraBold,color=if(total>=0)appGreen(LocalAppDark.current) else appRed(LocalAppDark.current))
            }
            entries.sortedByDescending{it.optString("id")}.forEachIndexed{idx,e->
                if(idx>0)HorizontalDivider(color=MaterialTheme.colorScheme.outlineVariant)
                Row(Modifier.fillMaxWidth().clickable{onEntryClick(e)}.padding(horizontal=16.dp,vertical=10.dp),verticalAlignment=Alignment.CenterVertically){
                    val reconciled=e.optBoolean("reconciled")
                    Box(Modifier.size(22.dp).border(2.dp,if(reconciled)InkSoft else MaterialTheme.colorScheme.outline,RoundedCornerShape(50)).background(if(reconciled)InkSoft else Color.Transparent,RoundedCornerShape(50)).clickable{onToggleReconciled(e)},contentAlignment=Alignment.Center){if(reconciled)Text("✓",fontSize=12.sp,fontWeight=FontWeight.Bold,color=Color.White)}
                    Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(e.optString("title"),fontSize=15.sp,fontWeight=FontWeight.Bold,maxLines=1);if(e.optString("category").isNotBlank())Text(e.optString("category"),fontSize=12.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)}
                    val positive=e.optString("type")=="einnahme"||e.optString("type")=="income";Text((if(positive) "+" else "-")+money(e.optDouble("amount")),fontSize=15.sp,fontWeight=FontWeight.ExtraBold,color=if(positive)appGreen(LocalAppDark.current) else appRed(LocalAppDark.current))
                }
            }
        }
    }
}
@Composable private fun ChevronIcon(left:Boolean,color:Color){Canvas(Modifier.size(20.dp)){val stroke=Stroke(width=2.4.dp.toPx(),cap=StrokeCap.Round,join=StrokeJoin.Round);val x1=if(left)size.width*.63f else size.width*.37f;val x2=if(left)size.width*.37f else size.width*.63f;drawLine(color,Offset(x1,size.height*.25f),Offset(x2,size.height*.5f),strokeWidth=stroke.width,cap=StrokeCap.Round);drawLine(color,Offset(x2,size.height*.5f),Offset(x1,size.height*.75f),strokeWidth=stroke.width,cap=StrokeCap.Round)}}
@Composable private fun IncomeExpenseBar(income:Double,expense:Double){val total=(income+expense).takeIf{it>0}?:1.0;val left=(income/total).toFloat().coerceIn(0f,1f);Row(Modifier.fillMaxWidth().padding(top=12.dp).height(20.dp).clip(RoundedCornerShape(10.dp))){Box(Modifier.weight(left.coerceAtLeast(.001f)).fillMaxHeight().background(Green).padding(start=8.dp),contentAlignment=Alignment.CenterStart){if(left>.22f)Text(money(income),color=Color.White,fontSize=11.sp,fontWeight=FontWeight.Bold,maxLines=1)};Box(Modifier.weight((1-left).coerceAtLeast(.001f)).fillMaxHeight().background(Red).padding(end=8.dp),contentAlignment=Alignment.CenterEnd){if(1-left>.22f)Text(money(expense),color=Color.White,fontSize=11.sp,fontWeight=FontWeight.Bold,maxLines=1)}}}

private fun Modifier.subViewSwipe(views:List<String>,current:String,onChange:(String)->Unit)=pointerInput(views,current){awaitPointerEventScope{while(true){val down=awaitFirstDown(requireUnconsumed=false);val start=down.position;var end=start;var pressed=true;while(pressed){val event=awaitPointerEvent();val change=event.changes.firstOrNull{it.id==down.id}?:break;end=change.position;pressed=change.pressed};val dx=end.x-start.x;val dy=end.y-start.y;val idx=views.indexOf(current);if(kotlin.math.abs(dx)>=60f&&kotlin.math.abs(dx)>=kotlin.math.abs(dy)*1.3f&&idx>=0){if(dx<0&&idx<views.lastIndex)onChange(views[idx+1]) else if(dx>0&&idx>0)onChange(views[idx-1])}}}}
@Composable private fun BookingsScreen(state:JSONObject,repo:HouseholdRepository){
 var revision by remember{mutableStateOf(0)};revision
 val income=repo.array(state,"income");val fixed=repo.array(state,"fixedExpenses");val invoices=repo.array(state,"openInvoices");var view by remember{mutableStateOf("rechnungen")};var paidOpen by remember{mutableStateOf(repo.getSetting("household-show-paid-invoices")=="1")}
 fun changed(){repo.save(state);revision++}
 Column(Modifier.fillMaxSize().subViewSwipe(listOf("rechnungen","einnahmen","fixkosten"),view){view=it}.padding(horizontal=18.dp)){Row(Modifier.fillMaxWidth().background(MaterialTheme.colorScheme.background,RoundedCornerShape(14.dp)).padding(4.dp)){OriginalSubNav("Rechnungen",view=="rechnungen",Modifier.weight(1f)){view="rechnungen"};OriginalSubNav("Einnahmen",view=="einnahmen",Modifier.weight(1f)){view="einnahmen"};OriginalSubNav("Fixkosten",view=="fixkosten",Modifier.weight(1f)){view="fixkosten"}};Spacer(Modifier.height(18.dp))
  when(view){"rechnungen"->{val all=invoices.objects();val open=all.filter{!it.optBoolean("paid")};val paid=all.filter{it.optBoolean("paid")}.sortedByDescending{it.optString("paidDate")};val today=LocalDate.now();val overdue=open.count{runCatching{LocalDate.parse(it.optString("dueDate")).isBefore(today)}.getOrDefault(false)}
   LazyColumn{item{OriginalHero("Offene Rechnungen gesamt",money(open.sumOf{it.optDouble("amount")}),"Rechnungen",open.size.toString(),"Davon überfällig",overdue.toString(),true)};if(open.isEmpty())item{OriginalEmpty("Keine offenen Rechnungen eingetragen.")};items(open.sortedBy{it.optString("dueDate")},key={it.optString("id")}){InvoiceEditableRow(it,state,repo,::changed)};item{PaidInvoicesHeader(paid.size,paidOpen){paidOpen=!paidOpen;repo.setSetting("household-show-paid-invoices",if(paidOpen)"1" else "0")}};if(paidOpen){if(paid.isEmpty())item{Text("Noch keine bezahlten Rechnungen.",Modifier.fillMaxWidth().padding(horizontal=4.dp,vertical=14.dp),textAlign=TextAlign.Center,color=InkSoft)}else items(paid,key={it.optString("id")}){PaidInvoiceEditableRow(it,state,repo,::changed)}}}}
   "einnahmen"->{val incomeTotal=sum(income,"amount");val activeLoanMonthly=repo.array(state,"loans").objects().filter{it.optDouble("remainingBalance")>0}.sumOf{it.optDouble("monthlyPayment")};val rest=incomeTotal-sum(fixed,"amount")-repo.array(state,"variableCosts").objects().sumOf{it.optDouble("monthlyAmount")}-activeLoanMonthly-(repo.getSetting("household-tilgung-extra")?.toDoubleOrNull()?:0.0);OriginalHero("Einnahmen gesamt",money(incomeTotal),"Einträge",income.length().toString(),"Monatlicher Rest",money(rest));LazyColumn{if(income.length()==0)item{OriginalEmpty("Noch nichts eingetragen.")};items(income.objects(),key={it.optString("id")}){EditableMoneyRow(it,state,repo,income,true,::changed)}}}
   else->{val manual=sum(fixed,"amount");val activeLoans=repo.array(state,"loans").objects().filter{it.optDouble("remainingBalance")>0};val loanTotal=activeLoans.sumOf{it.optDouble("monthlyPayment")};val extra=repo.getSetting("household-tilgung-extra")?.toDoubleOrNull()?.takeIf{it>=0}?:0.0;val vcNeed=repo.array(state,"variableCosts").objects().sumOf{it.optDouble("monthlyAmount")};val auto=loanTotal+extra+vcNeed;OriginalHero("Fixkosten gesamt",money(manual),"Einträge",fixed.length().toString(),"Inkl. automatisch",money(manual+auto));LazyColumn{if(fixed.length()==0)item{OriginalEmpty("Noch nichts eingetragen.")};groupFixed(fixed.objects()).forEach{g->item(key="group-"+g.first){EditableFixedGroup(g.first,g.second,state,repo,fixed,::changed)}};if(auto>0)item{AutoFixedGroup(loanTotal,extra,vcNeed)}}}
  }
 }
}
